    processor: unified({ rehypePlugins: [rehypePhotos] })
  },
  vite: {
    plugins: [tailwindcss()]
  },
  fonts: [
    {
      name: 'Open Sans',
      cssVariable: '--font-open-sans',
      provider: fontProviders.google(),
      weights: [400, 700],
      styles: ['normal']
    },
    {
      name: 'Literata',
      cssVariable: '--font-literata',
      provider: fontProviders.google(),
      weights: [400],
      styles: ['normal']
    }
  ]
});

