// @ts-check
import { defineConfig, fontProviders } from 'astro/config';

import tailwindcss from '@tailwindcss/vite';
import sitemap from '@astrojs/sitemap';
import { unified } from '@astrojs/markdown-remark';
import { rehypePhotos } from './src/lib/rehype-photos.ts';

// https://astro.build/config
export default defineConfig({
  site: 'https://johnchque.com/',
  integrations: [sitemap()],
  markdown: {
    // Astro 7 defaults to the native Sätteri processor; staying on the
    // classic unified/remark/rehype pipeline here since rehype-photos.ts
    // does non-trivial AST work (paragraph->figure rewriting) and Sätteri's
    // own plugin API/porting docs are still new.
    processor: unified({ rehypePlugins: [rehypePhotos] })
  },
  vite: {
    plugins: [tailwindcss()]
  },
  fonts: [
    {
      name: 'Open Sans',
      cssVariable: '--font-open-sans',
      provider: fontProviders.google(),
      weights: [400, 700],
      styles: ['normal']
    }
  ]
});

---
import { Font } from "astro:assets";
import "../styles/global.css";

interface Props {
	title?: string;
	description?: string;
	image?: string;
}

const siteName = "John Choque";
const defaultDescription =
	"John Choque — Software Engineer and Social Entrepreneur. Photos, albums, and writing.";

const {
	title,
	description = defaultDescription,
	image = "/og-default.png",
} = Astro.props;
const pageTitle = title ? `${title} · ${siteName}` : siteName;
const canonicalURL = new URL(Astro.url.pathname, Astro.site);
const ogImageURL = new URL(image, Astro.site);
---

<!doctype html>
<html lang="en">
	<head>
		<meta charset="utf-8" />
		<script is:inline>
			(function () {
				const stored = localStorage.getItem("theme");
				const prefersDark = window.matchMedia(
					"(prefers-color-scheme: dark)",
				).matches;
				if (stored === "dark" || (!stored && prefersDark)) {
					document.documentElement.classList.add("dark");
				}
			})();
		</script>
		<meta name="viewport" content="width=device-width, initial-scale=1" />
		<link rel="icon" type="image/svg+xml" href="/favicon.svg" />
		<link rel="icon" href="/favicon.ico" />
		<meta name="generator" content={Astro.generator} />
		<title>{pageTitle}</title>
		<meta name="description" content={description} />
		<link rel="canonical" href={canonicalURL} />

		<meta property="og:type" content="website" />
		<meta property="og:site_name" content={siteName} />
		<meta property="og:title" content={pageTitle} />
		<meta property="og:description" content={description} />
		<meta property="og:url" content={canonicalURL} />
		<meta property="og:image" content={ogImageURL} />

		<meta name="twitter:card" content="summary_large_image" />
		<meta name="twitter:title" content={pageTitle} />
		<meta name="twitter:description" content={description} />
		<meta name="twitter:image" content={ogImageURL} />

		<Font cssVariable="--font-open-sans" preload />
	</head>
	<body
		class="bg-mist text-ink transition-colors duration-700 ease-in-out dark:bg-charcoal dark:text-chalk"
	>
		<header
			class="fixed inset-x-0 top-0 z-10 flex max-w-4xl items-start justify-between p-4 text-white mix-blend-difference md:p-6 lg:p-8"
		>
			<div>
				<a href="/">John Choque</a>
				<p class="opacity-70">Building meaninfgul tech</p>
			</div>
			<nav class="flex flex-col items-end gap-1">
				<!-- <a
					href="/photos/"
					class="underline hover:text-evening dark:hover:text-sunset"
					>Photos</a
				>
				<a
					href="/albums/"
					class="underline hover:text-evening dark:hover:text-sunset"
					>Albums</a
				> -->
				<button
					id="theme-toggle"
					type="button"
					aria-label="Toggle color theme"
					class="mt-1 grid size-4 place-items-center self-end hover:text-evening dark:hover:text-sunset"
				>
					<svg
						class="col-start-1 row-start-1 dark:hidden"
						xmlns="http://www.w3.org/2000/svg"
						width="16"
						height="16"
						viewBox="0 0 24 24"
						fill="currentColor"
						><path
							d="M10 6C10 10.4183 13.5817 14 18 14C19.4386 14 20.7885 13.6203 21.9549 12.9556C21.4738 18.0302 17.2005 22 12 22C6.47715 22 2 17.5228 2 12C2 6.79948 5.9698 2.52616 11.0444 2.04507C10.3797 3.21152 10 4.56142 10 6ZM4 12C4 16.4183 7.58172 20 12 20C14.9654 20 17.5757 18.3788 18.9571 15.9546C18.6407 15.9848 18.3214 16 18 16C12.4772 16 8 11.5228 8 6C8 5.67863 8.01524 5.35933 8.04536 5.04293C5.62119 6.42426 4 9.03458 4 12ZM18.1642 2.29104L19 2.5V3.5L18.1642 3.70896C17.4476 3.8881 16.8881 4.4476 16.709 5.16417L16.5 6H15.5L15.291 5.16417C15.1119 4.4476 14.5524 3.8881 13.8358 3.70896L13 3.5V2.5L13.8358 2.29104C14.5524 2.1119 15.1119 1.5524 15.291 0.835829L15.5 0H16.5L16.709 0.835829C16.8881 1.5524 17.4476 2.1119 18.1642 2.29104ZM23.1642 7.29104L24 7.5V8.5L23.1642 8.70896C22.4476 8.8881 21.8881 9.4476 21.709 10.1642L21.5 11H20.5L20.291 10.1642C20.1119 9.4476 19.5524 8.8881 18.8358 8.70896L18 8.5V7.5L18.8358 7.29104C19.5524 7.1119 20.1119 6.5524 20.291 5.83583L20.5 5H21.5L21.709 5.83583C21.8881 6.5524 22.4476 7.1119 23.1642 7.29104Z"
						></path></svg
					>
					<svg
						class="col-start-1 row-start-1 hidden dark:inline"
						width="16"
						height="16"
						xmlns="http://www.w3.org/2000/svg"
						viewBox="0 0 24 24"
						fill="currentColor"
						><path
							d="M12 18C8.68629 18 6 15.3137 6 12C6 8.68629 8.68629 6 12 6C15.3137 6 18 8.68629 18 12C18 15.3137 15.3137 18 12 18ZM12 16C14.2091 16 16 14.2091 16 12C16 9.79086 14.2091 8 12 8C9.79086 8 8 9.79086 8 12C8 14.2091 9.79086 16 12 16ZM11 1H13V4H11V1ZM11 20H13V23H11V20ZM3.51472 4.92893L4.92893 3.51472L7.05025 5.63604L5.63604 7.05025L3.51472 4.92893ZM16.9497 18.364L18.364 16.9497L20.4853 19.0711L19.0711 20.4853L16.9497 18.364ZM19.0711 3.51472L20.4853 4.92893L18.364 7.05025L16.9497 5.63604L19.0711 3.51472ZM5.63604 16.9497L7.05025 18.364L4.92893 20.4853L3.51472 19.0711L5.63604 16.9497ZM23 11V13H20V11H23ZM4 11V13H1V11H4Z"
						></path></svg
					>
				</button>
			</nav>
		</header>
		<main class="max-w-2xl p-4 pt-28 md:p-6 md:pt-28 lg:p-8 lg:pt-32">
			<slot />
		</main>
		<script is:inline>
			document
				.getElementById("theme-toggle")
				?.addEventListener("click", () => {
					const isDark =
						document.documentElement.classList.toggle("dark");
					localStorage.setItem("theme", isDark ? "dark" : "light");
				});
		</script>
	</body>
</html>

